发现第n行是由两段第n-2^x行和一串0构成的因此 递归就被发现惹
#include&lt;bits/stdc++.h&gt;#include&lt;cstdlib&gt;#define For(i,a,b) for(register int i=a; i&lt;=b;++i)#define foR(i,a,b) for(register int i=a; i&gt;=b;--i)#define int long long#define db long doubleusing namespace std;const int N=2020;int T,n,k,f[505];void print(int x){    if(x==0)return ;    if(x==1){        cout&lt;&lt;k&lt;&lt;" ";        return ;    }    int id=lower_bound(f+1,f+1+32,x)-f-1;    // cout&lt;&lt;"!!!"&lt;&lt;x&lt;&lt;" "&lt;&lt;f[id]&lt;&lt;endl;    print(x-f[id]);    For(i,1,x-(x-f[id])*2)cout&lt;&lt;"0 ";    print(x-f[id]);}signed main(){    std::ios::sync_with_stdio(false);    std::cin.tie(nullptr);    cin&gt;&gt;T;    f[0]=1;    For(i,1,32)f[i]=f[i-1]*2;    while(T--){        cin&gt;&gt;n&gt;&gt;k;        print(n);        cout&lt;&lt;endl;    }}

(x+k)+(y+k)=(x+k)^(y+k)给你两个正整数  和  ().请找出一个非负整数 ,使得  成立, 或者确定这样的整数不存在.
首先要观察出  究竟意味着什么其实就是X和Y在二进制下每位不全为1然后构造就很容易：假设x&gt;y 那么当我们的k能够让 x+k 凑得二进制下形如10000000的数即最高位再进一位其余位均为零因为y&lt;x 因此y+k无论如何都不会像x+k一样最高位进位而且x的其余位都保证为零了 所以   就可以很显然地成立了
int solve(){    int x,y,ans=0,k=0;    cin&gt;&gt;x&gt;&gt;y;    if(x==y){        return -1;    }    if(x&lt;y)swap(x,y);    while(x){        if(x%2&amp;&amp;x!=1){            ans += (1&lt;&lt;k);            x+=1;        }        k++;x/=2;    }    return ans;}

树的遍历犯了一个致命错误（在把后序遍历的根节点从中序找出来后自以为是地 认为 中序遍历的 右半部分的第一个节点 就必定和 后序遍历的 右半部分的第一个节点 相同
int p=0;For(i,l,r-1){    if(a[i]==b[o+1])p=i;}dfs(l,p-1,s,o-1,k+1);dfs(p,r-1,o+1,t,k+1);
那我简单举个例子 你不就炸了吗^^
42 4 3 12 1 3 4

所以我是傻逼吗 我既然在中序遍历那部分把左边和右边的大小也都得到了 我在后序遍历不就马上得到了？因此正确代码如下
#include &lt;bits/stdc++.h&gt;#include &lt;cstdlib&gt;#define For(i,a,b) for(int i=a;i&lt;=b;++i)#define foR(i,a,b) for(int i=a;i&gt;=b;--i)using namespace std;const int N = 33;int n,a[N],b[N],K=0,cnt=0,A[33];vector&lt;int&gt; ans[N];void dfs(int l,int r,int s,int t,int k){ //Hou lr  Zhong st    int o=0;    K=max(K,k);    ans[k].push_back(a[r]);    if(l==r)return ;    // printf("!! %d %d %d %d %d !!\n",l,r,s,t,k);    For(i,s,t){        if(a[r]==b[i])o=i;    }    if(s==o){        dfs(l,r-1,s+1,t,k+1);    }    else if(o==t){        dfs(l,r-1,s,t-1,k+1);    }    else{        dfs(l,l+(o-s)-1,s,o-1,k+1);        dfs(r-(t-o),r-1,o+1,t,k+1);    }}signed main(){    cin&gt;&gt;n;    For(i,1,n)cin&gt;&gt;a[i];    For(i,1,n)cin&gt;&gt;b[i];    dfs(1,n,1,n,1);    For(i,1,K){        for(auto j : ans[i]){            A[++cnt] = j;        }    }    For(i,1,cnt-1) cout&lt;&lt;A[i]&lt;&lt;" ";    cout&lt;&lt;A[cnt];}



因为向下取整 所以 
 也就左右
因为每个k值只能用一次 因此我们可以背包f[i][j]表示 时的最小花费
然后 当时统计答案就好了

For(i,0,64)For(j,0,64)f[i][j]=inf;    f[0][0]=0;    For(k,0,64){        foR(i,64,0){            foR(j,64,0){                if(i &gt;= k){                    if(f[i][j] == inf)f[i][j] = f[i-k][j] + s[k];//防inf+inf爆炸                    else f[i][j]=min(f[i][j], f[i-k][j] + s[k]);                }                if(j &gt;= k){                    if(f[i][j] == inf)f[i][j] = f[i][j-k] + s[k];                    else f[i][j]=min(f[i][j], f[i][j-k] + s[k]);                }                            }        }    }

新手dp给定一个正整数 n，求将其分解成若干个素数之和的方案总数。
signed main(){    cin&gt;&gt;n;    ss();    f[0]=1;    For(i,1,cnt){        For(j,p[i],n){            f[j] += f[j-p[i]] ;        }    }    // 这样还保证了 y= a + b + c + ...  a、b、c是单调不递减的 因此不会有重复的问题    cout &lt;&lt; f[n] ;}

树型dp输入点数为N一棵树求树上长度恰好为K的路径个数f[i][j]表示以i为根出发i的子树到i距离为j的路径数然后 统计本节点子树到另一子树的距离为k的路径数给答案 
void dfs(int x,int fa){    dp[x][0]=1;    for(int i=Head[x];i;i=Next[i]){        int y=To[i];        if(y==fa)continue;        dfs(y,x);        For(j,1,k) dp[x][j]+=dp[y][j-1];    }    ans += dp[x][k];    int res = 0;    for(int i=Head[x];i;i=Next[i]){        int y=To[i];        if(y==fa)continue;        For(j,1,k-1)        res += (dp[x][j]-dp[y][j-1])*dp[y][k-j-1];    }    ans += res&gt;&gt;1;}

2025.3.24 - 2025.3.30


TIL/模拟题目保证了操作次数在以内 因此很好猜出可以进行次操作 使得字符串得到TIL各n个咋操作呢？我们发现如果先插到前面的话，后面序号数都会增大，会变麻烦，因此我们从后往前插就ok了。具体就是弄个栈 节点信息包括当前序号、当前插入的字母、和一个旁边的字母(我选取右边的) 真的只要模拟就好了 
#include &lt;bits/stdc++.h&gt;#include &lt;cstdlib&gt;#define For(i,a,b) for(int i=a;i&lt;=b;++i)#define foR(i,a,b) for(int i=a;i&gt;=b;--i)using namespace std;#define int long longconst int N=167;int n,ans[N*2],cnt;string s;struct Node{    int p;    char ch;    char lf;}hh;char nx(char x,char y){    if(x=='T'&amp;&amp;y=='I')return 'L';    if(x=='I'&amp;&amp;y=='T')return 'L';    if(x=='T'&amp;&amp;y=='L')return 'I';    if(x=='L'&amp;&amp;y=='T')return 'I';    if(x=='I'&amp;&amp;y=='L')return 'T';    if(x=='L'&amp;&amp;y=='I')return 'T';}stack&lt;Node&gt;q;void qwq(Node x){    Node y;    y=x; swap(y.ch,y.lf);    q.push(y);    y=x; y.p++; y.ch=nx(x.ch,x.lf); y.lf=x.lf;    q.push(y);    return ;}void OwO(int a,int b,int c,char A,char B,char C){    while(1){        Node x=q.top();q.pop();        if(x.ch==B&amp;&amp;b&lt;a){            ans[++cnt]=x.p;            b++; qwq(x);        }        if(x.ch==C&amp;&amp;c&lt;a){            ans[++cnt]=x.p;            c++; qwq(x);        }        if(x.ch==A&amp;&amp;a&lt;n){            ans[++cnt]=x.p;            a++; qwq(x);        }        if(a==b&amp;&amp;a==c)break;        if(q.empty())break;        if(cnt==2*n)break;    }    if(a==b&amp;&amp;a==c){        cout&lt;&lt;cnt&lt;&lt;endl;        For(i,1,cnt){            cout&lt;&lt;ans[i]&lt;&lt;endl;        }        return ;    }    else{        cout&lt;&lt;"-1\n";        return ;    }}void solve(){    cin&gt;&gt;n;    cin&gt;&gt;s;s='!'+s;    int a,b,c;    cnt=0;a=0;b=0;c=0;    while(!q.empty())q.pop();    For(i,1,n){        if(s[i]=='T')a++;        if(s[i]=='I')b++;        if(s[i]=='L')c++;        if(s[i]!=s[i+1]&amp;&amp;i!=n){            q.push({i,nx(s[i],s[i+1]),s[i+1]});        }    }    if(a==n||b==n||c==n){        cout&lt;&lt;-1&lt;&lt;endl;        return;    }    if(a&gt;=b&amp;&amp;a&gt;=c){        OwO(a,b,c,'T','I','L');return ;    }    if(b&gt;=a&amp;&amp;b&gt;=c){        OwO(b,a,c,'I','T','L');return ;    }    if(c&gt;=a&amp;&amp;c&gt;=b){        OwO(c,a,b,'L','T','I');return ;    }}signed main(){    ios::sync_with_stdio(0);    cin.tie(0),cout.tie(0);    int T;    cin&gt;&gt;T;    while(T--){        solve();    }    return 0;}
ps:一开始没优化结构 bro打了190多行（嘻嘻
莫队本以为是莫队 但其实还有超简便的做法注意到一个数可能对一个询问产生贡献的必要条件的是其出现过至少次，这样的数不超过个，对于每个这样的数记出现次数的前缀和，对于询问暴力枚举所有这样的数并通过前缀和查询该数的出现次数即可。
signed main(){    read(n);read(m);    For(i,1,n){        read(x);a[i]=x;        if(x&lt;=n)cnt[x]++;    }    For(i,1,n){        if(cnt[i]&gt;=i)val[++tot]=i;    }    For(i,1,tot){        For(j,1,n){            sum[i][j]=sum[i][j-1];            if(a[j]==val[i])sum[i][j]++;                    }    }    while(m--){        read(l);read(r);        ans=0;        For(j,1,min(tot,r-l+1)){            if(sum[j][r]-sum[j][l-1] == val[j])ans++;            if(val[j]&gt;r-l+1)break;        }        printf("%d\n",ans);    }}
